//! Deterministic source assets. Inputs are editable data; generated byte/layout
//! decisions are shared by native commands and the existing script bindings.
use crate::{text, Adapter, Error, Result};
use serde_json::{json, Value};
pub mod dy;
pub mod fonts;
pub mod logo;
pub mod manual;
pub fn assertion(message: impl Into<String>) -> Error {
    Error {
        kind: "AssertionError".into(),
        code: String::new(),
        message: message.into(),
    }
}
fn array(v: &Value) -> Result<&Vec<Value>> {
    v.as_array()
        .ok_or_else(|| Error::value("expected asset array"))
}
fn exact(v: &Value, n: usize) -> Result<&Vec<Value>> {
    let a = array(v)?;
    if a.len() != n {
        return Err(assertion(""));
    }
    Ok(a)
}
pub fn pattern_data() -> Value {
    serde_json::from_str(include_str!("../../../tools/data/patterns.json"))
        .expect("checked pattern data")
}
pub fn fontsets() -> Value {
    serde_json::from_str(include_str!("../../../tools/data/fontsets.json"))
        .expect("checked font data")
}
pub fn bits(grid: &str) -> Result<u16> {
    if grid.len() != 16 || !grid.bytes().all(|c| c == b'x' || c == b'.') {
        return Err(assertion(grid));
    }
    Ok(grid
        .bytes()
        .enumerate()
        .fold(0, |bits, (i, c)| bits | if c == b'x' { 1 << i } else { 0 }))
}
pub fn pattern_header(pieces: &Value) -> Result<String> {
    let pieces = exact(pieces, 10)?;
    let mut lines=vec!["/* SPDX-License-Identifier: GPL-3.0-only */".to_string(),"/* the pieces' factory drum patterns: written by tools/gen_pats.py (edit the grids there).".into()," * Bit s: a hit on step s; lanes: kick, snare, clap, closed hat, open hat, perc. */".into(),"const uint16_t EN_PIECE_PATS[EN_NPIECES][EN_NPAT][EN_NLANE] = {".into()];
    for piece in pieces {
        let p = exact(piece, 3)?;
        lines.push(format!("    /* {}: {} */", text(&p[0])?, text(&p[1])?));
        lines.push("    {".into());
        for (i, pattern) in exact(&p[2], 6)?.iter().enumerate() {
            let p = exact(pattern, 7)?;
            let mut comment = format!("        /* {} {}", i + 1, text(&p[0])?);
            let mut words = Vec::new();
            for (j, lane) in ["K", "S", "C", "H", "O", "P"].iter().enumerate() {
                let grid = text(&p[j + 1])?;
                comment += &format!("\n         *   {lane} {grid}");
                words.push(format!("0x{:04X}u", bits(grid)?));
            }
            comment += " */";
            lines.push(comment);
            lines.push(format!("        {{{}}},", words.join(", ")));
        }
        lines.push("    },".into());
    }
    lines.push("};".into());
    Ok(lines.join("\n") + "\n")
}
pub fn sine_header() -> String {
    let mut out="/* generated by tools/gen_sint.c: the sine table, 1024 points a turn and one more (4100 bytes in flash instead of RAM) */\nstatic const float SINT[1025] = {\n".to_string();
    // The same rounded f32 as C's FM_TWO_PI, before its f32 division.
    let step = core::f32::consts::TAU / 1024.0f32;
    for i in 0..=1024 {
        let x = fm1_engine::effects::math::sin(i as f32 * step);
        let value = format!("{:.9e}", f64::from(x));
        let (mantissa, exponent) = value.split_once('e').unwrap();
        let exponent = exponent.parse::<i32>().unwrap();
        let mantissa = scientific_mantissa(x, mantissa, exponent, cfg!(windows));
        if i % 6 == 0 {
            out += "    ";
        }
        out += &format!("{mantissa}e{exponent:+03}f,");
        out += if i % 6 == 5 || i == 1024 { "\n" } else { " " };
    }
    out += "};\n";
    out
}
fn scientific_mantissa(x: f32, nearest_even: &str, exponent: i32, legacy_ties: bool) -> String {
    // Legacy Windows printf rounds an exact decimal halfway away from zero.
    // Rust/modern libc choose the even digit. Detect the exact rational midpoint
    // with integers: a binary32 is M*2^E; decimal scaling adds 5^D*2^D.
    // This does not re-round the engine sample or use approximate f64 products.
    if legacy_ties {
        let bits = x.to_bits() & 0x7fff_ffff;
        let raw = (bits >> 23) as i32;
        let m = (bits & 0x7f_ffff) | if raw == 0 { 0 } else { 1 << 23 };
        let e = if raw == 0 { -149 } else { raw - 127 - 23 };
        let d = 9 - exponent;
        if d >= 0 && e + d < 0 {
            if let Some((n, den)) = 5_u128
                .checked_pow(d as u32)
                .and_then(|p| p.checked_mul(u128::from(m)))
                .zip(1_u128.checked_shl((-e - d) as u32))
            {
                let floor = n / den;
                if n % den == den / 2 && floor % 2 == 0 {
                    let rounded = floor + 1;
                    return format!(
                        "{}{}.{:09}",
                        if x.is_sign_negative() { "-" } else { "" },
                        rounded / 1_000_000_000,
                        rounded % 1_000_000_000
                    );
                }
            }
        }
    }
    nearest_even.to_owned()
}
pub fn request(method: &str, v: &Value, io: &mut impl Adapter) -> Result<Value> {
    let a = &v["args"];
    if let Some(method) = method.strip_prefix("font.") {
        return fonts::request(method, v, io);
    }
    if let Some(method) = method.strip_prefix("dy.") {
        return dy::request(method, v, io);
    }
    if let Some(method) = method.strip_prefix("logo.") {
        return logo::request(method, v, io);
    }
    if let Some(method) = method.strip_prefix("manual.") {
        return manual::request(method, v, io);
    }
    Ok(match method {
        "pattern-data" => pattern_data(),
        "fontsets" => fontsets(),
        "bits" => json!(bits(text(&a[0])?)?),
        "patterns" => json!(pattern_header(&a[0])?),
        "sine" => json!(sine_header()),
        _ => return Err(Error::value("unknown asset method")),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn exact_midpoint_matches_both_c_runtime_rounding_profiles() {
        for (x, even, legacy) in [
            (f32::from_bits(0xbf3c_a000), "-7.368164062", "-7.368164063"),
            (f32::from_bits(0x3f3c_a000), "7.368164062", "7.368164063"),
            (0.5, "5.000000000", "5.000000000"),
        ] {
            assert_eq!(scientific_mantissa(x, even, -1, false), even);
            assert_eq!(scientific_mantissa(x, even, -1, true), legacy);
        }
    }
}
